const CLIENT = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ding & Learn Online</title>
<style>
:root{--bg:#0b1020;--panel:#141b31;--card:#202a48;--text:#f8f9ff;--muted:#aeb8d2;--accent:#ffb21c;--good:#31d18b;--bad:#ff667e}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#28365f,#0b1020 55%);color:var(--text);font-family:system-ui,Segoe UI,Arial,sans-serif;min-height:100vh}.wrap{max-width:1000px;margin:auto;padding:18px}
h1{margin:0;font-size:clamp(28px,6vw,46px)}.sub{color:var(--muted);margin:3px 0 18px}.panel{background:#11172bdd;border:1px solid #ffffff18;border-radius:22px;padding:16px;box-shadow:0 20px 50px #0005}
.start{max-width:560px;margin:8vh auto}.start form{display:grid;gap:10px}input{width:100%;padding:13px;border-radius:12px;border:1px solid #ffffff20;background:#0a1020;color:#fff;font-size:16px}
button{border:0;border-radius:13px;padding:13px 16px;font-weight:900;cursor:pointer;font-size:15px}.primary{background:var(--accent);color:#121622}.dark{background:#26304d;color:#fff}.danger{background:var(--bad);color:#fff}
.hidden{display:none!important}.top{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap}.room{font-weight:950;letter-spacing:2px;background:#ffffff0d;padding:10px 14px;border-radius:12px}.layout{display:grid;grid-template-columns:280px 1fr;gap:15px}.scores{display:grid;gap:8px;margin-top:12px}.score{display:flex;justify-content:space-between;padding:10px;border-radius:12px;background:#ffffff08}.reader{outline:2px solid var(--accent)}
select{width:100%;padding:10px;background:#0b1020;color:#fff;border:1px solid #ffffff20;border-radius:10px}
.game{text-align:center;min-height:600px}.meta{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}.badge{padding:7px 11px;border-radius:999px;background:#ffffff0d;color:var(--muted);font-weight:800;font-size:12px}.die{font-size:46px;color:var(--accent);margin:8px}.card{background:linear-gradient(145deg,#202b4b,#161c32);border:1px solid #ffffff18;border-radius:24px;padding:28px 20px;min-height:280px;display:flex;flex-direction:column;justify-content:center;margin:8px auto 14px;max-width:680px}.clue{color:var(--accent);font-weight:950}.q{font-size:clamp(22px,4vw,34px);font-weight:850;line-height:1.2;margin:15px}.ans{font-size:25px;font-weight:950;color:var(--good);min-height:34px}.timer{font-size:50px;font-weight:950}.warn{color:var(--bad)}.dings{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px;max-width:680px;margin:auto}.dings button{background:#ffefc2;border:3px solid #d99a00}.actions{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:10px}.status{min-height:28px;color:var(--muted);font-weight:800;margin:10px}.note{font-size:12px;color:var(--muted);line-height:1.45;margin-top:12px}
@media(max-width:760px){.layout{grid-template-columns:1fr}.game{min-height:0}.card{min-height:300px}}
</style>
</head>
<body>
<div class="wrap">
<section id="start" class="panel start">
<h1>🎓 Ding & Learn</h1><div class="sub">Real-time multiplayer • 2–8 players</div>
<form id="joinForm">
<input id="name" maxlength="20" placeholder="Your name" required>
<input id="code" maxlength="6" placeholder="Room code (leave blank to create)">
<div class="actions"><button class="primary" id="joinBtn" type="submit">Create room</button></div>
</form><div class="note">Share the 6-character room code with friends. Everyone can join from a different phone.</div>
</section>

<section id="game" class="hidden">
<div class="top"><div><h1>🎓 Ding & Learn</h1><div class="sub">First to 7 cards wins</div></div><div class="room">ROOM <span id="roomCode">—</span></div></div>
<div class="layout">
<aside class="panel">
<label>Reader</label><select id="reader"></select>
<div class="actions"><button class="primary" id="newRound">🎲 New round</button><button class="dark" id="reset">Reset</button></div>
<div class="scores" id="scores"></div>
<div class="note">The host controls rounds and scoring. The server records the first DING.</div>
</aside>
<main class="panel game">
<div class="meta"><span class="badge" id="card">Card —</span><span class="badge" id="level">Level —</span></div>
<div class="die" id="die">🎲</div>
<div class="card"><div class="clue" id="clue">Waiting for host…</div><div class="q" id="question">Press New round to begin.</div><div class="ans hidden" id="answer"></div></div>
<div class="timer" id="timer">—</div>
<div class="dings" id="dings"></div>
<div class="status" id="status">Waiting…</div>
<div class="actions"><button class="dark" id="reveal">👁 Reveal</button><button class="primary" id="correct">✓ Correct</button><button class="danger" id="wrong">✕ Wrong</button></div>
</main>
</div>
</section>
</div>
<script src="/socket.io/socket.io.js"></script>
<script>
const socket=io(), $=id=>document.getElementById(id), faces=["⚀","⚁","⚂","⚃","⚄","⚅"];
let roomCode="", me="", state=null, cards=[], timerId=null, currentWinner=null;

cards=QUESTION_DATA;
function msg(t,cls=""){ $("status").textContent=t; $("status").className="status "+cls; }
function isHost(){return state&&state.hostId===me}
function cardData(){return state?.round?cards.find(c=>c.id===state.round.cardId):null}
function render(){
 if(!state)return;
 $("roomCode").textContent=state.code;
 $("newRound").disabled=!isHost(); $("reset").disabled=!isHost();
 $("reader").disabled=!isHost();
 $("reader").innerHTML=state.players.map(p=>\`<option value="\${p.id}" \${p.id===state.readerId?"selected":""}>\${esc(p.name)}</option>\`).join("");
 $("scores").innerHTML=state.players.map(p=>\`<div class="score \${p.id===state.readerId?"reader":""}"><span>\${esc(p.name)}</span><b>\${p.score}</b></div>\`).join("");
 const r=state.round, c=cardData();
 if(!r||!c){
   $("card").textContent="Card —";$("level").textContent="Level —";$("die").textContent="🎲";
   $("clue").textContent="Waiting for host…";$("question").textContent="Press New round to begin.";
   $("answer").classList.add("hidden");$("timer").textContent="—";
 }else{
   const q=c.riddles[r.level];
   $("card").textContent=\`Card \${c.id} / \${cards.length}\`;$("level").textContent=q.level;
   $("die").textContent=faces[r.roll-1]||"🎲";$("clue").textContent=q.clue;$("question").textContent=q.riddle;
   $("answer").textContent=q.answer;
   $("answer").classList.toggle("hidden",!state.answerShown);
   currentWinner=r.dingId;
   renderTimer();
 }
 $("dings").innerHTML=state.players.map(p=>\`<button \${!r||r.dingId?"disabled":""} data-ding="\${p.id}">🔔 \${esc(p.name)}</button>\`).join("");
 if(r?.dingId){
   const p=state.players.find(x=>x.id===r.dingId);
   msg(\`\${p?p.name:"Someone"} dinged first — answer now!\`);
 } else if(r) msg("First player to press DING gets 5 seconds.");
}
function renderTimer(){
 clearInterval(timerId);
 if(!state?.round?.dingId){$("timer").textContent="—";return}
 const end=state.round.startedAt + 5000;
 const tick=()=>{const left=Math.max(0,end-Date.now());$("timer").textContent=(left/1000).toFixed(1);$("timer").classList.toggle("warn",left<=2000);if(left<=0)clearInterval(timerId)};
 tick();timerId=setInterval(tick,50);
}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}

$("joinForm").onsubmit=e=>{e.preventDefault();const name=$("name").value.trim();const code=$("code").value.trim().toUpperCase();
 if(!name)return; me=""; const event=code?"joinRoom":"createRoom";
 socket.emit(event,{name,code},res=>{if(!res.ok)return alert(res.error);roomCode=res.code;});
};
socket.on("state",s=>{state=s; if(!me){const mine=s.players.find(p=>p.name===$("name").value.trim());if(mine)me=mine.id}
 $("start").classList.add("hidden");$("game").classList.remove("hidden");render();});
socket.on("ding",d=>{currentWinner=d.playerId;navigator.vibrate?.(90);render();});
socket.on("resolved",d=>{if(d.winner)alert(\`🏆 \${d.winner.name} wins the game!\`);render();});

$("newRound").onclick=()=>socket.emit("newRound",{code:roomCode});
$("reset").onclick=()=>socket.emit("resetGame",{code:roomCode});
$("reader").onchange=e=>socket.emit("setReader",{code:roomCode,playerId:e.target.value});
$("reveal").onclick=()=>{const c=cardData();if(c){$("answer").textContent=c.riddles[state.round.level].answer;$("answer").classList.remove("hidden");}};
$("correct").onclick=()=>{if(isHost())socket.emit("resolve",{code:roomCode,correct:true})};
$("wrong").onclick=()=>{if(isHost())socket.emit("resolve",{code:roomCode,correct:false})};
$("dings").onclick=e=>{const id=e.target.dataset.ding;if(id)socket.emit("ding",{code:roomCode})};
</script>
</body></html>
`;

app.get("/", (req,res) => {
  res.type("html").send(CLIENT);
});

const rooms = new Map();

function roomCode() {
  let code;
  do { code = crypto.randomBytes(3).toString("hex").toUpperCase(); }
  while (rooms.has(code));
  return code;
}
function cleanName(name) {
  return String(name || "Player").replace(/[<>]/g, "").trim().slice(0,20) || "Player";
}
function publicRoom(room) {
  return {
    code:room.code, hostId:room.hostId, readerId:room.readerId,
    players:[...room.players.values()].map(p=>({id:p.id,name:p.name,score:p.score,dinged:p.dinged})),
    round:room.round ? {
      cardId:room.round.cardId, level:room.round.level, roll:room.round.roll,
      startedAt:room.round.startedAt, dingId:room.round.dingId
    } : null
  };
}
function broadcast(room){io.to(room.code).emit("state",publicRoom(room));}
function makeRound(){
  const card=QUESTIONS[Math.floor(Math.random()*QUESTIONS.length)];
  const roll=1+Math.floor(Math.random()*6);
  return {cardId:card.id,level:roll<=2?0:roll<=4?1:2,roll,startedAt:Date.now(),dingId:null};
}

io.on("connection",socket=>{
  socket.on("createRoom",({name},cb)=>{
    const code=roomCode();
    const room={code,hostId:socket.id,readerId:socket.id,players:new Map(),round:null};
    room.players.set(socket.id,{id:socket.id,name:cleanName(name),score:0,dinged:false});
    rooms.set(code,room); socket.join(code); cb({ok:true,code}); broadcast(room);
  });
  socket.on("joinRoom",({code,name},cb)=>{
    const room=rooms.get(String(code||"").toUpperCase().trim());
    if(!room)return cb({ok:false,error:"Room not found."});
    if(room.players.size>=8)return cb({ok:false,error:"Room is full (8 players)."});
    room.players.set(socket.id,{id:socket.id,name:cleanName(name),score:0,dinged:false});
    socket.join(room.code); cb({ok:true,code:room.code}); broadcast(room);
  });
  socket.on("setReader",({code,playerId})=>{
    const room=rooms.get(code); if(!room||room.hostId!==socket.id||!room.players.has(playerId))return;
    room.readerId=playerId; broadcast(room);
  });
  socket.on("newRound",({code})=>{
    const room=rooms.get(code); if(!room||room.hostId!==socket.id)return;
    for(const p of room.players.values())p.dinged=false;
    room.round=makeRound(); broadcast(room);
  });
  socket.on("ding",({code})=>{
    const room=rooms.get(code);
    if(!room||!room.round||room.round.dingId||!room.players.has(socket.id))return;
    room.round.dingId=socket.id; room.round.dinggedAt=Date.now();
    for(const p of room.players.values())p.dinged=p.id===socket.id;
    io.to(room.code).emit("ding",{playerId:socket.id,at:room.round.dinggedAt}); broadcast(room);
  });
  socket.on("resolve",({code,correct})=>{
    const room=rooms.get(code); if(!room||room.hostId!==socket.id||!room.round)return;
    const id=room.round.dingId;
    if(correct&&id&&room.players.has(id))room.players.get(id).score++;
    else if(!correct&&room.players.has(room.readerId))room.players.get(room.readerId).score++;
    const winner=[...room.players.values()].find(p=>p.score>=7);
    io.to(room.code).emit("resolved",{correct:!!correct,winner:winner?{id:winner.id,name:winner.name}:null});
    room.round=null; broadcast(room);
  });
  socket.on("resetGame",({code})=>{
    const room=rooms.get(code); if(!room||room.hostId!==socket.id)return;
    for(const p of room.players.values())p.score=0; room.round=null; broadcast(room);
  });
  socket.on("disconnect",()=>{
    for(const [code,room] of rooms){
      if(!room.players.has(socket.id))continue;
      room.players.delete(socket.id);
      if(room.hostId===socket.id){
        const next=room.players.values().next().value;
        if(!next){rooms.delete(code);continue}
        room.hostId=next.id;
      }
      if(room.readerId===socket.id)room.readerId=room.hostId;
      if(room.round?.dingId===socket.id)room.round.dingId=null;
      broadcast(room);
    }
  });
});

